input.command:
W=~/development/stallion-worktrees/bootstrap; cd $W && mkdir -p .github/workflows crates/server/src apps/web/src apps/web/e2e && for p in geometry schema client-store client-sync; do mkdir -p packages/$p/src; cat > packages/$p/package.json <<EOF
{
  "name": "@stallion/$p",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  }
}
EOF
cat > packages/$p/src/index.ts <<EOF
export const packageName = "@stallion/$p";
EOF
cat > packages/$p/src/index.test.ts <<EOF
import { expect, test } from "vitest";
import { packageName } from "./index";

test("exposes its package name", () => {
  expect(packageName).toBe("@stallion/$p");
});
EOF
done
cat > .gitignore <<'EOF'
node_modules/
dist/
target/
crates/server/build/
.wrangler/
.tmp/
test-results/
playwright-report/
EOF
cat > rust-toolchain.toml <<'EOF'
[toolchain]
channel = "stable"
components = ["rustfmt", "clippy"]
targets = ["wasm32-unknown-unknown"]
EOF
cat > Cargo.toml <<'EOF'
[workspace]
resolver = "3"
members = ["crates/server"]

[profile.release]
opt-level = "s"
lto = true
codegen-units = 1
EOF
cat > crates/server/Cargo.toml <<'EOF'
[package]
name = "stallion-server"
version = "0.0.0"
edition = "2024"
publish = false

[lib]
crate-type = ["cdylib", "rlib"]

[dependencies]
worker = "0.8.6"
worker-macros = "0.8.6"
EOF
cat > crates/server/src/lib.rs <<'EOF'
use worker::*;

pub fn health() -> &'static str {
    "ok"
}

#[event(fetch)]
async fn fetch(_req: Request, _env: Env, _ctx: Context) -> Result<Response> {
    Response::ok(health())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn health_reports_ok() {
        assert_eq!(health(), "ok");
    }
}
EOF
cat > wrangler.jsonc <<'EOF'
{
  "$schema": "node_modules/wrangler/config-schema.json",
  "name": "stallion",
  "main": "crates/server/build/index.js",
  "compatibility_date": "2026-09-25",
  "build": {
    "command": "npm run build:worker"
  },
  "assets": {
    "directory": "./apps/web/dist",
    "not_found_handling": "single-page-application"
  }
}
EOF
cat > package.json <<'EOF'
{
  "name": "stallion",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "workspaces": ["packages/*", "apps/*"],
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "fix": "biome check --write . && cargo fmt --all",
    "lint": "biome check .",
    "lint:rust": "cargo fmt --all --check && cargo clippy --workspace --all-targets -- -D warnings",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "vitest run",
    "test:rust": "cargo test --workspace",
    "build": "npm run build --workspaces --if-present",
    "build:worker": "cd crates/server && worker-build --release"
  }
}
EOF
cat > tsconfig.json <<'EOF'
{
  "compilerOptions": {
    "target": "ES2023",
    "lib": ["ES2023", "DOM", "DOM.Iterable"],
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "jsx": "react-jsx",
    "jsxImportSource": "preact",
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true,
    "noImplicitOverride": true,
    "noFallthroughCasesInSwitch": true,
    "verbatimModuleSyntax": true,
    "isolatedModules": true,
    "skipLibCheck": true,
    "noEmit": true,
    "types": []
  },
  "include": ["packages/*/src", "apps/*/src", "apps/*/e2e", "apps/*/*.config.ts", "vitest.config.ts"]
}
EOF
cat > vitest.config.ts <<'EOF'
import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    include: ["{packages,apps}/*/src/**/*.test.{ts,tsx}"],
  },
});
EOF
cat > apps/web/package.json <<'EOF'
{
  "name": "@stallion/web",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build",
    "test:e2e": "playwright test"
  }
}
EOF
cat > apps/web/index.html <<'EOF'
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Stallion</title>
  </head>
  <body>
    <div id="app"></div>
    <script type="module" src="/src/main.tsx"></script>
  </body>
</html>
EOF
cat > apps/web/vite.config.ts <<'EOF'
import preact from "@preact/preset-vite";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [preact()],
});
EOF
cat > apps/web/src/app.tsx <<'EOF'
export function App() {
  return <main>Stallion</main>;
}
EOF
cat > apps/web/src/main.tsx <<'EOF'
import { render } from "preact";
import { App } from "./app";

const root = document.getElementById("app");
if (!root) throw new Error("Missing #app root element in index.html");
render(<App />, root);
EOF
cat > apps/web/src/app.test.tsx <<'EOF'
import { expect, test } from "vitest";
import { App } from "./app";

test("renders the app shell", () => {
  const shell = App();
  expect(shell.type).toBe("main");
  expect(shell.props.children).toBe("Stallion");
});
EOF
cat > apps/web/playwright.config.ts <<'EOF'
import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: "./e2e",
  use: { baseURL: "http://localhost:4173" },
  webServer: {
    command: "npm run build && npx vite preview --port 4173 --strictPort",
    url: "http://localhost:4173",
    reuseExistingServer: false,
  },
  projects: [
    { name: "desktop", use: { ...devices["Desktop Chrome"] } },
    { name: "tablet", use: { ...devices["Galaxy Tab S4"] } },
  ],
});
EOF
cat > apps/web/e2e/smoke.spec.ts <<'EOF'
import { expect, test } from "@playwright/test";

test("loads the app shell", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("main")).toHaveText("Stallion");
});
EOF
echo done

